<?= $this->extend('layouts/app') ?><?= $this->section('content') ?><?= view('partials/breadcrumbs',['title'=>$title,'subtitle'=>current_role()==='borrower'?'Browse equipment currently registered in the barangay inventory.':'Manage barangay equipment inventory and availability.']) ?><section class="panel"><div class="panel-head"><form class="toolbar" method="get"><input type="search" name="q" value="<?= esc((string)service('request')->getGet('q')) ?>" placeholder="Search asset code or equipment"><select name="category_id"><option value="">All categories</option><?php foreach($categories as $c): ?><option value="<?= $c['id'] ?>" <?= (string)service('request')->getGet('category_id')===(string)$c['id']?'selected':'' ?>><?= esc($c['name']) ?></option><?php endforeach; ?></select><?php if(current_role()!=='borrower'): ?><select name="status"><option value="">All statuses</option><?php foreach(config('BantayGamit')->equipmentStatuses as $k=>$v): ?><option value="<?= esc($k) ?>" <?= service('request')->getGet('status')===$k?'selected':'' ?>><?= esc($v) ?></option><?php endforeach; ?></select><?php endif; ?><button class="btn" type="submit">Filter</button><?php if(service('request')->getGet('q')||service('request')->getGet('category_id')||service('request')->getGet('status')): ?><a class="btn ghost" href="<?= site_url('equipment') ?>">Clear</a><?php endif; ?></form><?php if(current_role()!=='borrower'): ?><a class="btn primary" href="<?= site_url('equipment/new') ?>"><?= ui_icon('plus') ?> Add Equipment</a><?php endif; ?></div><p class="result-count"><?= (int)$total ?> equipment record(s)</p><div class="table-wrap" role="region" aria-label="Equipment inventory table" tabindex="0"><table><thead><tr><th>Asset</th><th>Category</th><th>Location</th><th class="number">Total</th><th class="number">Available</th><th>Condition</th><th>Status</th><th class="actions-head">Actions</th></tr></thead><tbody><?php foreach($equipment as $e): ?><tr><td><b><?= esc($e['name']) ?></b><small><?= esc($e['asset_code']) ?></small></td><td><?= esc($e['category_name']) ?></td><td><?= esc($e['location_name']) ?></td><td class="number"><?= (int)$e['total_quantity'] ?> <?= esc($e['unit']) ?></td><td class="number"><strong><?= (int)$e['available_quantity'] ?></strong></td><td><?= view('partials/status_badge',['status'=>$e['condition']]) ?></td><td><?= view('partials/status_badge',['status'=>$e['status']]) ?></td><td class="actions"><a class="btn small" href="<?= site_url('equipment/'.$e['id']) ?>">View</a><?php if(current_role()!=='borrower'&&$e['status']!=='retired'): ?><a class="btn small ghost" href="<?= site_url('equipment/'.$e['id'].'/edit') ?>">Edit</a><?php endif; ?></td></tr><?php endforeach; ?><?php if(empty($equipment)): ?><tr><td colspan="8"><div class="empty">No equipment matches your filters.</div></td></tr><?php endif; ?></tbody></table></div><?php if($pagerLinks): ?><div class="pager" aria-label="Equipment pagination"><?= $pagerLinks ?></div><?php endif; ?></section><?= $this->endSection() ?>
